#!/usr/bin/env python3
"""Render assets/stats card for the profile README from live GitHub data.

Runs in GitHub Actions with nothing but the standard library: the fonts the
card uses are embedded below as glyph outlines (JetBrains Mono, Unbounded —
both SIL Open Font License), so the card looks the same in every browser.

    GITHUB_TOKEN=... python3 profile_stats.py --user <login> --out dist/stats.svg
    python3 profile_stats.py --demo --out stats-demo.svg      # offline preview
"""
import argparse
import datetime as dt
import json
import os
import sys
import time
import urllib.request

QUERY = """
query($login: String!) {
  user(login: $login) {
    followers { totalCount }
    repositories(first: 100, ownerAffiliations: OWNER, isFork: false, privacy: PUBLIC,
                 orderBy: {field: STARGAZERS, direction: DESC}) {
      totalCount
      nodes {
        stargazerCount
        languages(first: 10, orderBy: {field: SIZE, direction: DESC}) {
          edges { size node { name color } }
        }
      }
    }
    contributionsCollection {
      totalPullRequestContributions
      contributionCalendar {
        totalContributions
        weeks { contributionDays { date contributionCount } }
      }
    }
  }
}
"""
# Used when the token may not read everything above: contributions only.
QUERY_MIN = """
query($login: String!) {
  user(login: $login) {
    contributionsCollection {
      contributionCalendar {
        totalContributions
        weeks { contributionDays { date contributionCount } }
      }
    }
  }
}
"""
