class QueryError(RuntimeError):
    pass


def fetch(login, token):
    try:
        return _fetch(QUERY, login, token)
    except QueryError as e:
        print(f"full query refused ({e}); falling back to contributions only", file=sys.stderr)
        return _fetch(QUERY_MIN, login, token)


def _fetch(query, login, token):
    body = json.dumps({"query": query, "variables": {"login": login}}).encode()
    last = None
    for attempt in range(4):
        req = urllib.request.Request("https://api.github.com/graphql", data=body, headers={
            "Authorization": f"bearer {token}", "Content-Type": "application/json",
            "User-Agent": "profile-stats"})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                data = json.load(r)
            if data.get("errors"):
                raise QueryError(json.dumps(data["errors"])[:500])
            return data["data"]["user"]
        except QueryError:
            raise
        except Exception as e:  # network blips and 502s from the API are worth a retry
            last = e
            time.sleep(2 ** attempt * 3)
    raise SystemExit(f"GitHub API failed: {last}")


def summarize(user):
    cal = user["contributionsCollection"]["contributionCalendar"]
    days = [(d["date"], d["contributionCount"]) for w in cal["weeks"] for d in w["contributionDays"]]
    weeks = [(w["contributionDays"][0]["date"], sum(d["contributionCount"] for d in w["contributionDays"]))
             for w in cal["weeks"] if w["contributionDays"]]
    counts = [c for _, c in days]
    i = len(counts) - 1
    if i >= 0 and counts[i] == 0:      # today is not over yet
        i -= 1
    current = 0
    while i >= 0 and counts[i] > 0:
        current += 1
        i -= 1
    longest = run = 0
    for c in counts:
        run = run + 1 if c > 0 else 0
        longest = max(longest, run)
    langs = {}
    stars = 0
    repos = user.get("repositories") or {"totalCount": None, "nodes": []}
    for repo in repos["nodes"]:
        stars += repo["stargazerCount"]
        for e in repo["languages"]["edges"]:
            name = e["node"]["name"]
            if name in SKIP_LANGUAGES:
                continue
            size, color = langs.get(name, (0, e["node"]["color"]))
            langs[name] = (size + e["size"], color or "#8B5CF6")
    total = sum(s for s, _ in langs.values()) or 1
    top = sorted(langs.items(), key=lambda kv: -kv[1][0])[:4]
    return dict(
        total=cal["totalContributions"], current=current, longest=longest, weeks=weeks[-53:],
        active=sum(1 for c in counts if c > 0),
        stars=stars if repos["totalCount"] is not None else None, repos=repos["totalCount"],
        followers=(user.get("followers") or {}).get("totalCount"),
        prs=user["contributionsCollection"].get("totalPullRequestContributions"),
        langs=[(n, s / total, c) for n, (s, c) in top if s / total >= 0.01],
        updated=days[-1][0] if days else dt.date.today().isoformat())


# ------------------------------------------------------------------ drawing
_used = set()


def text(font, s, size, x, y, anchor="start", tracking=0.0, fill="#fff", extra=""):
    f = ATLAS[font]
    sc = size / 100.0
    adv = [f.get(ch, f["?"])[0] for ch in s]
    w = (sum(adv) + tracking * 100 * max(len(s) - 1, 0)) * sc
    if anchor == "middle":
        x -= w / 2
    elif anchor == "end":
        x -= w
    parts, cx = [], 0.0
    for ch, a in zip(s, adv):
        key = ch if ch in f else "?"
        if f[key][1]:
            _used.add((font, key))
            parts.append(f'<use href="#{font}{ord(key):x}" x="{cx:.0f}"/>')
        cx += a + tracking * 100
    return (f'<g transform="translate({x:.1f} {y:.1f}) scale({sc:.4f})" fill="{fill}"{extra}>'
            f'{"".join(parts)}</g>'), w


def chip(x, y, label, value):
    v, vw = text("m7", value, 14, x + 14, y + 21, fill=C["text"])
    l, lw = text("m5", label, 12.5, x + 14 + vw + 8, y + 21, tracking=0.08, fill=C["muted"])
    w = 14 + vw + 8 + lw + 14
    return f'<rect x="{x}" y="{y}" width="{w:.1f}" height="32" rx="16" fill="#10101D" stroke="#26263F"/>{v}{l}', w


def render(s):
    W, H = 1200, 340
    o = []
    o.append(text("m5", "CONTRIBUTIONS  ·  LAST 12 MONTHS", 13.5, 56, 74, tracking=0.16, fill=C["muted"])[0])
    total = f"{s['total']:,}"
    big, bw = text("num", total, 64, 54, 152, fill="#fff")
    # a gradient cannot span several <use> glyphs, so paint it through a mask
    o.append(f'<mask id="mn" maskUnits="userSpaceOnUse" x="0" y="0" width="{W}" height="{H}">{big}</mask>'
             f'<linearGradient id="gn" x1="0" x2="1"><stop offset="0" stop-color="{C["cyan"]}"/>'
             f'<stop offset=".55" stop-color="{C["violet"]}"/><stop offset="1" stop-color="{C["magenta"]}"/></linearGradient>'
             f'<rect x="54" y="96" width="{bw + 4:.0f}" height="64" fill="url(#gn)" mask="url(#mn)"/>')
    # a streak of 0 or 1 says little; the year's active days always say something
    first = ("CURRENT STREAK", s["current"]) if s["current"] >= 2 else ("ACTIVE DAYS", s["active"])
    for i, (lab, val) in enumerate((first, ("LONGEST STREAK", s["longest"]))):
        x = 56 + i * 190
        o.append(text("m5", lab, 12.5, x, 204, tracking=0.12, fill=C["muted"])[0])
        v, vw = text("num", str(val), 30, x, 242, fill=C["text"])
        o.append(v)
        o.append(text("m5", "day" if val == 1 else "days", 14, x + vw + 8, 242, fill=C["text2"])[0])
    # live pill
    upd = "UPDATED " + s["updated"]
    t, tw = text("m7", upd, 12, 1144 - 14, 75, anchor="end", tracking=0.08, fill="#CFFBEA")
    px = 1144 - tw - 42
    o.append(f'<rect x="{px:.1f}" y="57" width="{tw + 42:.1f}" height="26" rx="13" fill="#0E1A17" stroke="#1F5A45"/>')
    o.append(f'<circle class="ping" cx="{px + 15:.1f}" cy="70" r="3.5" fill="{C["green"]}"/><circle cx="{px + 15:.1f}" cy="70" r="3.5" fill="{C["green"]}"/>')
    o.append(t)
    # weekly bars
    weeks = s["weeks"]
    x0, x1, base, top = 476, 1144, 226, 104
    n = max(len(weeks), 1)
    step = (x1 - x0) / n
    bwid = max(step - 3.4, 2)
    mx = max([c for _, c in weeks] + [1])
    bars, labels, last_m, last_x = [], [], None, -99
    for i, (start, c) in enumerate(weeks):
        x = x0 + i * step
        h = 3 if c == 0 else max(6, (base - top) * (c / mx) ** 0.5)   # sqrt: one busy week does not flatten the rest
        fill = "#1C1C30" if c == 0 else "url(#gb)"
        cls = ' class="bar"' if c else ""
        bars.append(f'<rect{cls} x="{x:.1f}" y="{base - h:.1f}" width="{bwid:.1f}" height="{h:.1f}" rx="{min(3, bwid / 2):.1f}" '
                    f'fill="{fill}" style="animation-delay:{i * 18}ms"/>')
        m = start[:7]
        if m != last_m:
            if last_m is not None and x - last_x > 42:
                mon = dt.date(int(start[:4]), int(start[5:7]), 1).strftime("%b")
                labels.append(text("m5", mon, 12, x, 252, fill=C["muted"])[0])
                last_x = x
            last_m = m
    o.append(f'<path d="M{x0} {base + 1}H{x1}" stroke="{C["line"]}"/>')
    o += bars + labels
    o.append(f'<path d="M56 274H1144" stroke="{C["line"]}"/>')
    # chips
    cx = 56
    for label, val in (("STARS", s["stars"]), ("PUBLIC REPOS", s["repos"]), ("FOLLOWERS", s["followers"]), ("PULL REQUESTS", s["prs"])):
        if not val:
            continue
        c, w = chip(cx, 290, label, f"{val:,}")
        o.append(c)
        cx += w + 10
    # languages
    lx, lw = 760, 384
    langs = list(s["langs"])
    def legend_w(ls):
        tot_ = sum(p for _, p, _ in ls) or 1
        return sum(13 + text("m5", n, 12.5, 0, 0)[1] + 6 + text("m5", f"{round(100 * p / tot_)}%", 12.5, 0, 0)[1] + 16
                   for n, p, _ in ls) - 16
    while len(langs) > 1 and legend_w(langs) > lw:
        langs.pop()
    s = dict(s, langs=langs)
    if s["langs"]:
        segx = lx
        tot = sum(p for _, p, _ in s["langs"]) or 1
        o.append(f'<clipPath id="lc"><rect x="{lx}" y="292" width="{lw}" height="8" rx="4"/></clipPath><g clip-path="url(#lc)">')
        for name, p, col in s["langs"]:
            w = lw * p / tot
            o.append(f'<rect x="{segx:.1f}" y="292" width="{w + 1:.1f}" height="8" fill="{col}"/>')
            segx += w
        o.append("</g>")
        tx = lx
        for name, p, col in s["langs"]:
            o.append(f'<circle cx="{tx + 4}" cy="318" r="4" fill="{col}"/>')
            t1, w1 = text("m5", name, 12.5, tx + 13, 322, fill=C["text2"])
            t2, w2 = text("m5", f"{round(100 * p / tot)}%", 12.5, tx + 13 + w1 + 6, 322, fill=C["muted"])
            o += [t1, t2]
            tx += 13 + w1 + 6 + w2 + 16
    defs = "".join(f'<path id="{f}{ord(ch):x}" d="{ATLAS[f][ch][1]}"/>' for f, ch in sorted(_used))
    css = (".bar{transform-box:fill-box;transform-origin:bottom;animation:grow 1.1s cubic-bezier(.2,.7,.2,1) both}"
           "@keyframes grow{from{transform:scaleY(0)}}"
           ".ping{transform-box:fill-box;transform-origin:center;animation:ping 1.8s cubic-bezier(0,0,.2,1) infinite}"
           "@keyframes ping{0%{transform:scale(1);opacity:.9}100%{transform:scale(3.2);opacity:0}}"
           "@media (prefers-reduced-motion: reduce){*{animation:none!important}}")
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}" fill="none" role="img" aria-labelledby="t d">
<title id="t">GitHub activity</title>
<desc id="d">{s["total"]:,} contributions in the last 12 months on {s["active"]} active days; current streak {s["current"]} days, longest {s["longest"]} days.</desc>
<style>{css}</style>
<defs>{defs}
<clipPath id="cc"><rect width="{W}" height="{H}" rx="28"/></clipPath>
<linearGradient id="gb" x1="0" y1="{base}" x2="0" y2="{top}" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="{C["cyan"]}"/><stop offset=".55" stop-color="{C["violet"]}"/><stop offset="1" stop-color="{C["magenta"]}"/></linearGradient>
<linearGradient id="gbd" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{C["cyan"]}" stop-opacity=".7"/><stop offset=".5" stop-color="#fff" stop-opacity=".06"/><stop offset="1" stop-color="{C["magenta"]}" stop-opacity=".65"/></linearGradient>
<radialGradient id="g1"><stop offset="0" stop-color="{C["violet"]}" stop-opacity=".22"/><stop offset="1" stop-color="{C["violet"]}" stop-opacity="0"/></radialGradient>
<pattern id="pd" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#fff" fill-opacity=".06"/></pattern>
</defs>
<g clip-path="url(#cc)"><rect width="{W}" height="{H}" fill="{C["bg"]}"/><rect width="{W}" height="{H}" fill="url(#pd)"/>
<circle cx="820" cy="150" r="380" fill="url(#g1)"/></g>
<rect x=".75" y=".75" width="{W - 1.5}" height="{H - 1.5}" rx="27.25" stroke="url(#gbd)" stroke-width="1.5"/>
{"".join(o)}
</svg>'''


def demo():
    import random
    random.seed(4)
    start = dt.date.today() - dt.timedelta(days=364)
    start -= dt.timedelta(days=(start.weekday() + 1) % 7)
    weeks, d = [], start
    while d <= dt.date.today():
        days = []
        for _ in range(7):
            if d <= dt.date.today():
                days.append({"date": d.isoformat(), "contributionCount": random.choice([0, 0, 1, 2, 3, 5, 8, 13])})
            d += dt.timedelta(days=1)
        weeks.append({"contributionDays": days})
    total = sum(x["contributionCount"] for w in weeks for x in w["contributionDays"])
    return {"followers": {"totalCount": 12},
            "repositories": {"totalCount": 14, "nodes": [
                {"stargazerCount": 3, "languages": {"edges": [
                    {"size": 500, "node": {"name": "Python", "color": "#3572A5"}},
                    {"size": 200, "node": {"name": "TypeScript", "color": "#3178c6"}},
                    {"size": 90, "node": {"name": "JavaScript", "color": "#f1e05a"}},
                    {"size": 40, "node": {"name": "Shell", "color": "#89e051"}},
                    {"size": 900, "node": {"name": "Jupyter Notebook", "color": "#DA5B0B"}}]}}]},
            "contributionsCollection": {"totalPullRequestContributions": 41,
                                        "contributionCalendar": {"totalContributions": total, "weeks": weeks}}}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--user")
    ap.add_argument("--out", required=True)
    ap.add_argument("--demo", action="store_true")
    a = ap.parse_args()
    if a.demo:
        user = demo()
    else:
        token = os.environ.get("GITHUB_TOKEN")
        if not token or not a.user:
            raise SystemExit("needs --user and GITHUB_TOKEN")
        user = fetch(a.user, token)
        if user is None:
            raise SystemExit(f"no such user: {a.user}")
    svg = render(summarize(user))
    os.makedirs(os.path.dirname(a.out) or ".", exist_ok=True)
    with open(a.out, "w", encoding="utf-8") as f:
        f.write(svg)
    print(f"wrote {a.out} ({len(svg):,} bytes)")


if __name__ == "__main__":
    main()
